using ApiFromLecture.Models; using FluentValidation; namespace ApiFromLecture.Validation; public class CreateProductValidator:AbstractValidator<CreateProductRequest>{public CreateProductValidator(){RuleFor(x=>x.Name).NotEmpty().WithMessage("Имя обязательно").MinimumLength(3).MaximumLength(100);RuleFor(x=>x.Price).GreaterThan(0).LessThan(1_000_000);RuleFor(x=>x.CategoryId).GreaterThan(0);When(x=>x.Price>10000,()=>RuleFor(x=>x.Name).MinimumLength(10).WithMessage("Дорогие товары требуют длинного названия"));}}
